#!/usr/bin/env python3
"""PSB1 Median has no downloadable dataset (PSB1 instances are generated by the benchmark's code). This writes data in the PSB2 file format
under data/psb2/median-psb1: three integers in [-100, 100], the output is their median. Fixed seed; 1,000 random cases (no edge file in PSB1, so a few hand-chosen ones).
Section 145 of the findings log. Usage: scripts/psb1_median_prepare.py [dir]"""
import json, os, random, sys
D = os.path.join(sys.argv[1] if len(sys.argv) > 1 else "data/psb2", "median-psb1")
os.makedirs(D, exist_ok=True)
rng = random.Random(145)
def line(a, b, c):
    return json.dumps({"input1": a, "input2": b, "input3": c, "output1": sorted([a, b, c])[1]})
edge = [(0, 0, 0), (1, 2, 3), (3, 2, 1), (2, 1, 3), (-100, 100, 0), (5, 5, 1), (1, 5, 5), (-7, -7, -7), (100, 100, 100), (-100, -100, 100)]
with open(os.path.join(D, "median-psb1-edge.json"), "w") as f:
    f.write("\n".join(line(*e) for e in edge) + "\n")
with open(os.path.join(D, "median-psb1-random.json"), "w") as f:
    f.write("\n".join(line(rng.randint(-100, 100), rng.randint(-100, 100), rng.randint(-100, 100)) for _ in range(5000)) + "\n")
